        set_inheritable(target, True)
        if target not in prepared:
            prepared.append(target)
    return prepared


def _startupinfo(handle_list):
    """Build a STARTUPINFO carrying the inherited-handle list."""
    try:
        info = subprocess.STARTUPINFO()
    except AttributeError as exc:  # pragma: no cover - non-Windows stdlib
        raise WSpawnError(
            "this runtime cannot restrict handle inheritance: %s" % exc, kind="unsupported"
        ) from exc
    if not hasattr(info, "lpAttributeList"):  # pragma: no cover - very old runtime
        raise WSpawnError(
            "this runtime has no process attribute list, so handle inheritance "
            "cannot be restricted",
            kind="unsupported",
        )
    if handle_list:
        info.lpAttributeList = {"handle_list": list(handle_list)}
    return info


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child can reach the objects in ``inherit`` -- under the same handle
    values -- plus the standard streams given here, and nothing else of this
    process.  A standard stream left as ``None`` is wired to ``NUL`` rather
    than to this process's own stream, so a handover nobody asked for cannot
    happen by omission.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)
    _require_windows("spawn()")

    handle_list = _prepare_handover(handles)
    info = _startupinfo(handle_list)

    kwargs = {
        # close_fds=True is what makes the standard library attach the attribute
        # list and create the process with a *restricted* inherited set; with it
        # off, every inheritable object here would cross the boundary.
        "close_fds": True,
        "startupinfo": info,
        "stdin": subprocess.DEVNULL if stdin is None else stdin,
        "stdout": subprocess.DEVNULL if stdout is None else stdout,
        "stderr": subprocess.DEVNULL if stderr is None else stderr,
    }
    try:
        popen = subprocess.Popen(command, **kwargs)
    except WSpawnError:
        raise
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os") from exc
    except ValueError as exc:
        raise WSpawnError(str(exc), kind="badarg") from exc
    return SpawnedProcess(popen, handle_list)

"""Starting helper processes with a handover of the caller's objects.

The handover is done with an explicit inherited-handle list
(``PROC_THREAD_ATTRIBUTE_HANDLE_LIST``) attached to the process creation call.
That is the only mechanism on Windows that narrows inheritance to a chosen set:
``bInheritHandles`` on its own hands over *every* handle that happens to carry
``HANDLE_FLAG_INHERIT``, which is exactly the leak this module has to prevent.

Two properties follow from using the handle list, and callers rely on both:

* the child's handle table holds the listed objects and nothing else of ours,
  so other inheritable objects in this process stay private;
* an inherited handle keeps the *same numeric value* in the child, so the
  caller can pass the number along (argv, environment, a config blob) and the
  child can use it directly.
"""

import os
import subprocess

from . import _winapi
from .errors import WSpawnError
from .inherit import _require_windows, resolve_handle, set_inheritable

#: subprocess sentinels (PIPE/STDOUT/DEVNULL) and the standard descriptors are
#: never handle values, so only integers above this are considered for the
#: "caller passed a raw OS handle as a standard stream" fallback.
_STD_FD_MAX = 2


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, popen, inherit):
        self._popen = popen
        self.inherit = tuple(inherit)
        self.pid = popen.pid
        self.returncode = None
        self.stdin = popen.stdin
        self.stdout = popen.stdout
        self.stderr = popen.stderr

    def wait(self, timeout=None):
        self.returncode = self._popen.wait(timeout=timeout)
        return self.returncode

    def poll(self):
        self.returncode = self._popen.poll()
        return self.returncode

    def communicate(self, input=None, timeout=None):
        out = self._popen.communicate(input=input, timeout=timeout)
        self.returncode = self._popen.returncode
        return out

    def terminate(self):
        self._popen.terminate()

    def kill(self):
        self._popen.kill()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError("argv must be a sequence of arguments, not a single string", kind="badarg")
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError("argv must be an iterable of paths: %s" % exc, kind="badarg") from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    try:
        items = list(inherit)
    except TypeError as exc:
        raise WSpawnError("inherit must be a sequence of handles: %s" % exc, kind="badarg") from exc
    out = []
    for item in items:
        if isinstance(item, bool):
            raise WSpawnError(
                "inherit must contain integer handles, got %r" % (item,), kind="badarg"
            )
        try:
            out.append(int(item))
        except (TypeError, ValueError, OverflowError) as exc:
            raise WSpawnError(
                "inherit must contain integer handles: %s" % exc, kind="badarg"
            ) from exc
    return tuple(out)


def _prepare_handover(handles):
    """Resolve, validate and arm the handles that will cross the boundary.

    Returns the de-duplicated handle values for the inherited handle list, in
    the order the caller gave them.
    """
    prepared = []
    for handle in handles:
        target = resolve_handle(handle, "spawn()")
        if target & 3 == 3:
            # Legacy console pseudo handles (0x3, 0x7, 0xb, ...) cannot appear
            # in an inherited handle list; process creation rejects them.
            raise WSpawnError(
                "a console pseudo handle (%r) cannot be handed over explicitly; "
                "pass it as stdin/stdout/stderr instead" % (handle,),
                kind="unsupported",
                handle=handle,
            )
        # The handle list is only honoured for handles that are themselves
        # marked inheritable, so arm each one before process creation.
        set_inheritable(target, True)
        if target not in prepared:
            prepared.append(target)
    return prepared


def _is_open_fd(number):
    try:
        os.fstat(number)
    except (OSError, ValueError, OverflowError):
        return False
    return True


def _as_std_stream(value, name, opened):
    """Normalise one ``stdin``/``stdout``/``stderr`` argument for ``Popen``.

    ``None`` becomes ``NUL``: an unspecified standard stream must not quietly
    hand this process's own stream to the child.  A raw OS handle is accepted
    too -- it is wrapped in a throwaway descriptor over a *duplicate*, so the
    caller's handle is neither closed nor consumed.  Descriptors, file objects
    and the ``subprocess`` sentinels keep their usual meaning.
    """
    if value is None:
        return subprocess.DEVNULL
    if isinstance(value, bool) or not isinstance(value, int):
        return value
    if value <= _STD_FD_MAX or _is_open_fd(value):
        return value
    if not _winapi.is_windows() or not _winapi.is_valid_handle(value):
        return value

    import msvcrt
    import _winapi as _stdlib_winapi

    try:
        duplicate = _stdlib_winapi.DuplicateHandle(
            _stdlib_winapi.GetCurrentProcess(),
            value,
            _stdlib_winapi.GetCurrentProcess(),
            0,
            True,
            _stdlib_winapi.DUPLICATE_SAME_ACCESS,
        )
    except OSError as exc:
        raise WSpawnError(
            "cannot use %r as %s: %s" % (value, name, exc), kind="os", handle=value
        ) from exc
    try:
        fd = msvcrt.open_osfhandle(duplicate, 0)
    except (OSError, ValueError) as exc:
        _stdlib_winapi.CloseHandle(duplicate)
        raise WSpawnError(
            "cannot use %r as %s: %s" % (value, name, exc), kind="unsupported", handle=value
        ) from exc
    # open_osfhandle takes ownership of the duplicate; closing the descriptor
    # closes it, which is what `opened` is collected for.
    opened.append(fd)
    return fd


def _startupinfo(handle_list):
    """Build a STARTUPINFO carrying the inherited-handle list."""
    try:
        info = subprocess.STARTUPINFO()
    except AttributeError as exc:  # pragma: no cover - non-Windows stdlib
        raise WSpawnError(
            "this runtime cannot restrict handle inheritance: %s" % exc, kind="unsupported"
        ) from exc
    if not hasattr(info, "lpAttributeList"):  # pragma: no cover - very old runtime
        raise WSpawnError(
            "this runtime has no process attribute list, so handle inheritance "
            "cannot be restricted",
            kind="unsupported",
        )
    if handle_list:
        info.lpAttributeList = {"handle_list": list(handle_list)}
    return info


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child can reach the objects in ``inherit`` -- under the same handle
    values -- plus the standard streams given here, and nothing else of this
    process.  A standard stream left as ``None`` is wired to ``NUL`` rather
    than to this process's own stream, so a handover nobody asked for cannot
    happen by omission.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)
    _require_windows("spawn()")

    handle_list = _prepare_handover(handles)
    info = _startupinfo(handle_list)

    opened = []
    kwargs = {
        # close_fds=True is what makes the standard library attach the attribute
        # list and create the process with a *restricted* inherited set; with it
        # off, every inheritable object here would cross the boundary.
        "close_fds": True,
        "startupinfo": info,
    }
    try:
        kwargs["stdin"] = _as_std_stream(stdin, "stdin", opened)
        kwargs["stdout"] = _as_std_stream(stdout, "stdout", opened)
        kwargs["stderr"] = _as_std_stream(stderr, "stderr", opened)
        try:
            popen = subprocess.Popen(command, **kwargs)
        except WSpawnError:
            raise
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os") from exc
        except ValueError as exc:
            raise WSpawnError(str(exc), kind="badarg") from exc
    finally:
        for fd in opened:
            try:
                os.close(fd)
            except OSError:
                pass
    return SpawnedProcess(popen, handle_list)
